function normalizeRole(rawRole) {
  if (!rawRole) return USER_ROLES.DATA_ANALYST;
  const str = String(rawRole).trim().toLowerCase().replace(/[\s_-]+/g, '_');
  if (str === 'data_analyst' || str === 'analyst' || str === 'business_analyst' || str === 'student' || str === 'researcher') {
    return USER_ROLES.DATA_ANALYST;
  }
  if (str === 'data_scientist' || str === 'scientist' || str === 'ml_engineer' || str === 'ai_engineer') {
    return USER_ROLES.DATA_SCIENTIST;
  }
  if (str === 'project_manager' || str === 'pm' || str === 'product_manager' || str === 'program_manager') {
    return USER_ROLES.PROJECT_MANAGER;
  }
  if (str === 'admin' || str === 'administrator' || str === 'system_admin' || str === 'superadmin') {
    return USER_ROLES.ADMIN;
  }
  return USER_ROLES.DATA_ANALYST;
}

function hasPermission(userRole, permission) {
  if (!permission) return true;
  const canonicalRole = normalizeRole(userRole);
  const perms = ROLE_PERMISSIONS[canonicalRole] || [];
  if (perms.includes('*')) return true;
  return perms.includes(permission);
}

function can(userRole, permission) {
  return hasPermission(userRole, permission);
}

function hasRole(userRole, requiredRole) {
  const canonicalRole = normalizeRole(userRole);
  const requiredCanonical = normalizeRole(requiredRole);
  if (canonicalRole === USER_ROLES.ADMIN) return true;
  return canonicalRole === requiredCanonical;
}

function isDevelopmentEnvironment() {
  try {
    if (typeof window === 'undefined') return false;
    if (window.__INSIGHTIQ_PROD_MODE__ === true) return false;
    if (typeof process !== 'undefined' && process.env && process.env.NODE_ENV === 'production') return false;
    
    if (window.__INSIGHTIQ_DEV_MODE__ === true) return true;
    if (typeof process !== 'undefined' && process.env && process.env.NODE_ENV === 'development') return true;

    const hostname = window.location.hostname;
    const isLocalhost = hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '[::1]' || hostname.endsWith('.local');
    const isDevPort = window.location.port !== '' && window.location.port !== '80' && window.location.port !== '443';
    return isLocalhost || isDevPort;
  } catch (e) {
    return false;
  }
}

