function computeStageApplicability(columns = []) {
  if (!columns || columns.length === 0) {
    return {
      projectConfigured: true,
      datasetAttached: true,
      profilingComplete: true,
      analyticsComplete: true,
      geographicComplete: false,
      modelingComplete: true,
      reportGenerated: true,
      projectFinalized: true
    };
  }

  const numCols = columns.filter(c => c.is_numeric || (c.canonical_type && c.canonical_type === 'number'));
  const catCols = columns.filter(c => c.is_categorical);
  const geoCols = columns.filter(c => c.is_geographic || ['country', 'region', 'state', 'city', 'location', 'territory'].some(k => (c.column_name || '').toLowerCase().includes(k)));

  const hasNumericData = numCols.length > 0;
  const hasCategoricalData = catCols.length > 0;
  const hasGeographicData = geoCols.length > 0;

  return {
    projectConfigured: true,
    datasetAttached: true,
    profilingComplete: true,
    analyticsComplete: hasNumericData || hasCategoricalData,
    geographicComplete: hasGeographicData,
    modelingComplete: hasNumericData,
    reportGenerated: true,
    projectFinalized: true
  };
}

function calculateProjectProgress(project, datasets = [], reports = [], columns = []) {
  if (!project) return { score: 0, completedCount: 0, totalStages: PROJECT_STAGE_DEFINITIONS.length, status: 'Not Started', stages: [] };

  const ws = { ...(project.workspaceState || {}) };

  // Infer associated dataset from datasets list if columns not passed directly
  let targetCols = Array.isArray(columns) && columns.length > 0 ? columns : [];
  const projectHasDatasetIds = Array.isArray(project.datasetIds) && project.datasetIds.length > 0;
  const projectHasDatasetNames = Array.isArray(project.datasetNames) && project.datasetNames.length > 0;
  const matchedDataset = (datasets || []).find(d => 
    (projectHasDatasetIds && project.datasetIds.includes(d.id)) ||
    (projectHasDatasetNames && project.datasetNames.includes(d.name)) ||
    (project.datasetNames && project.datasetNames.includes(d.original_filename)) ||
    d.projectId === project.id
  );

  if (targetCols.length === 0 && matchedDataset) {
    targetCols = matchedDataset.columns || [];
  }

  // 1. Stage 1: Project Created / Configured
  if (project.name && project.name.trim().length > 0) {
    ws.projectConfigured = true;
  }

  // 2. Stage 2: Dataset Connected / Attached
  if (projectHasDatasetIds || projectHasDatasetNames || matchedDataset) {
    ws.datasetAttached = true;
  }

  // 3. Stage 3: Dataset Profiled (has schema columns or quality metrics)
  if (matchedDataset?.quality_score != null || matchedDataset?.quality?.quality_score != null || targetCols.length > 0) {
    ws.profilingComplete = true;
  }

  // 4. Stage 4: Analysis Completed (profiled dataset ready or analysis performed)
  if (ws.profilingComplete && targetCols.length > 0) {
    if (ws.analyticsComplete !== false && (ws.analyticsComplete || project.analyticsReady || matchedDataset)) {
      ws.analyticsComplete = true;
    }
  }

  // 5. Stage 5: AI Insights / Modeling Generated
  if (ws.modelingComplete || ws.aiInsightsComplete || project.aiInsightsReady || (matchedDataset && targetCols.some(c => c.is_numeric))) {
    ws.modelingComplete = true;
  }

  // 6. Stage 6: Geographic Intelligence Completed (if applicable and geo analysis generated/available)
  const applicability = computeStageApplicability(targetCols);
  if (applicability.geographicComplete) {
    if (ws.geographicComplete == null && matchedDataset) {
      ws.geographicComplete = true;
    }
  }

  // 7. Stage 7: Report Generated
  if (reports && reports.length > 0) {
    const hasProjectReport = reports.some(r => 
      r.projectId === project.id || 
      (project.datasetIds && project.datasetIds.includes(r.datasetId)) ||
      (matchedDataset && r.datasetId === matchedDataset.id)
    );
    if (hasProjectReport) {
      ws.reportGenerated = true;
    }
  }

  let completedStages = 0;
  let applicableStages = 0;

  const stageStatuses = PROJECT_STAGE_DEFINITIONS.map(stage => {
    const isApplicable = applicability[stage.key] !== false;
    const isCompleted = !!ws[stage.key] && isApplicable;

    if (isApplicable) {
      applicableStages++;
      if (isCompleted) {
        completedStages++;
      }
    }

    return {
      ...stage,
      isCompleted: isCompleted && isApplicable,
      isApplicable
    };
  });

  const completionPercentage = applicableStages > 0 
    ? Math.min(100, Math.round((completedStages / applicableStages) * 100)) 
    : 0;

  let status = 'Not Started';
  if (completionPercentage >= 100 || ws.projectFinalized) {
    status = 'Completed';
  } else if (completionPercentage >= 75) {
    status = 'Nearly Complete';
  } else if (completionPercentage >= 50) {
    status = 'On Track';
  } else if (completionPercentage >= 25) {
    status = 'In Progress';
  }

  return {
    score: completionPercentage,
    completedCount: completedStages,
    applicableStages,
    totalStages: PROJECT_STAGE_DEFINITIONS.length,
    status,
    stages: stageStatuses,
    workspaceState: ws,
    applicability
  };
}

function generateProjectNameFromDatasetName(rawName) {
  if (!rawName || typeof rawName !== 'string') return 'Analytics Project';

  let clean = rawName
    .replace(/\.[^/.]+$/, '') // remove extension
    .replace(/[\-_.]+/g, ' ') // replace underscores, hyphens, dots with spaces
    .replace(/([a-z])([A-Z])/g, '$1 $2') // split camelCase
    .trim();

  // Remove common noise words if they appear at the end
  clean = clean.replace(/\b(dataset|data|telemetry|raw|export|table|file)\b/gi, '').trim();

  // Title Case each word
  const words = clean.split(/\s+/).filter(Boolean);
  if (words.length === 0) return 'Analytics Workspace';

  const titleCased = words.map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');

  if (!titleCased.toLowerCase().includes('analysis') && !titleCased.toLowerCase().includes('intelligence') && !titleCased.toLowerCase().includes('workspace') && !titleCased.toLowerCase().includes('project')) {
    return `${titleCased} Analysis`;
  }
  return titleCased;
}

function inferProjectCategory(columns = [], datasetName = '') {
  const colNames = (columns || []).map(c => (typeof c === 'string' ? c : c.column_name || c.name || '').toLowerCase());
  const nameStr = (datasetName || '').toLowerCase();
  const allText = colNames.join(' ') + ' ' + nameStr;

  if (/(customer|client|subscriber|user|churn|rfm|demographic|account|visitor)/i.test(allText)) {
    return 'Customer Analytics';
  }
  if (/(sales|order|sku|product|cart|checkout|shipping|merchant|store|e-commerce|ecommerce|retail)/i.test(allText)) {
    return 'E-commerce';
  }
  if (/(revenue|profit|cost|margin|tax|budget|cash|expense|invoice|financial|balance|ledger|fiscal)/i.test(allText)) {
    return 'Finance';
  }
  if (/(patient|diagnosis|drug|hospital|medical|treatment|clinical|physician|health)/i.test(allText)) {
    return 'Healthcare';
  }
  if (/(employee|salary|attrition|department|tenure|hiring|payroll|hr|job_title)/i.test(allText)) {
    return 'Human Resources';
  }
  if (/(inventory|warehouse|logistics|supplier|transit|fulfillment|supply_chain|supplychain|freight)/i.test(allText)) {
    return 'Supply Chain';
  }
  if (/(sensor|machine|factory|uptime|latency|throughput|fleet|network|device|iot|telemetry)/i.test(allText)) {
    return 'Operations';
  }
  return 'General Analytics';
}

function getNextActionForProject(progressDetails) {
  const stages = progressDetails?.stages || [];
  const nextIncomplete = stages.find(s => !s.isCompleted);

  if (!nextIncomplete) {
    return {
      title: 'Project Completed',
      description: 'All 8 lifecycle stages completed. Strategic initiative is ready for stakeholder delivery.',
      nav: 'projects',
      actionText: 'View Portfolio',
      stageKey: null
    };
  }

  switch (nextIncomplete.key) {
    case 'projectConfigured':
      return {
        title: 'Configure Project',
        description: 'Set up project name, category, and description.',
        nav: 'projects',
        actionText: 'Configure Project',
        stageKey: 'projectConfigured'
      };
    case 'datasetAttached':
      return {
        title: 'Attach Dataset',
        description: 'Upload or connect a source dataset to this project.',
        nav: 'datasets',
        actionText: 'Attach Dataset',
        stageKey: 'datasetAttached'
      };
    case 'profilingComplete':
      return {
        title: 'Profile Dataset & Review Quality',
        description: 'Run schema profiling, quality analysis, and explore data distributions.',
        nav: 'datasets',
        actionText: 'Profile Dataset',
        stageKey: 'profilingComplete'
      };
    case 'analyticsComplete':
      return {
        title: 'Run Analytics & Generate Insights',
        description: 'Perform multi-dimensional analysis and generate AI-powered insights.',
        nav: 'analytics',
        actionText: 'Launch Analytics Studio',
        stageKey: 'analyticsComplete'
      };
    case 'geographicComplete':
      return {
        title: 'Analyze Geographic Intelligence',
        description: 'Perform spatial analysis, regional aggregation, and geographic visualizations.',
        nav: 'geo',
        actionText: 'Open Geographic Intelligence',
        stageKey: 'geographicComplete'
      };
    case 'modelingComplete':
      return {
        title: 'Build Models & Run Forecasting',
        description: 'Configure ML pipelines, anomaly detection, and time-series forecasting.',
        nav: 'anomaly',
        actionText: 'Launch Modeling',
        stageKey: 'modelingComplete'
      };
    case 'reportGenerated':
      return {
        title: 'Generate Executive Report',
        description: 'Synthesize insights, metrics, and charts into an exportable report.',
        nav: 'reports',
        actionText: 'Generate Report',
        stageKey: 'reportGenerated'
      };
    case 'projectFinalized':
      return {
        title: 'Finalize & Archive Project',
        description: 'Review deliverables and mark the project as officially completed.',
        nav: 'projects',
        actionText: 'Finalize Project',
        stageKey: 'projectFinalized'
      };
    default:
      return {
        title: 'Continue Project Work',
        description: 'Explore dataset and advance project milestones.',
        nav: 'projects',
        actionText: 'Open Workspace',
        stageKey: null
      };
  }
}

