                    let valA = a[schemaSortField] || '';
                    let valB = b[schemaSortField] || '';
                    if (typeof valA === 'string') valA = valA.toLowerCase();
                    if (typeof valB === 'string') valB = valB.toLowerCase();
                    if (valA < valB) return schemaSortAsc ? -1 : 1;
                    if (valA > valB) return schemaSortAsc ? 1 : -1;
